const DEFAULT_MODES = [
  {
    key: 'eco', name: 'ECO MODE', resistance: '0.8Ω', material: 'Nic Salt',
    description: 'Delicate and smooth,\ndisposable-like flavor',
    caption: 'ECO MODE for Long Trip',
    coilFile: 'vast_05_2.webp', productFile: 'vast_06_1.webp', sceneFile: 'vast_06_2.webp',
    position: '52% center',
  },
  {
    key: 'nor', name: 'NOR MODE', resistance: '0.6Ω', material: '',
    description: 'Well balanced,\nSweetness and Aroma',
    caption: 'NOR MODE for Everyday',
    coilFile: 'vast_05_3.webp', productFile: 'vast_06_3.webp', sceneFile: 'vast_06_4.webp',
    position: '55% center',
  },
  {
    key: 'pwr', name: 'PWR MODE', resistance: '0.4Ω', material: 'Free Base (VG < 70%)',
    description: 'Bigger vapor production,\nhigh flavor production',
    caption: 'PWR MODE for Gathering Chill',
    coilFile: 'vast_05_4.webp', productFile: 'vast_06_5.webp', sceneFile: 'vast_06_6.webp',
    position: '54% center',
  },
];

const asset = (base, file) => `${String(base).replace(/\/$/, '')}/${file}`;
const distance = (value, fallback) => Number.isFinite(Number(value)) && Number(value) > 0 ? Number(value) : fallback;
const splitLines = (text) => String(text).split('\n').map((line, index) => <span key={index}>{line}</span>);

const Picture = ({ image, mobileImage, alt = '', className = '', style }) => (
  <picture className={className} style={style}>
    {mobileImage && <source media="(max-width: 1023px)" srcSet={mobileImage} />}
    <img src={image} alt={alt} loading="eager" decoding="async" />
  </picture>
);

const CoilLights = ({ count }) => (
  <span className="vast-tri-core__coil-lights" aria-hidden="true">
    {Array.from({ length: count }, (_, index) => (
      <svg key={index} viewBox="28 6 36 36"><path d={MODE_DOT_PATHS[0]} fill="currentColor" /></svg>
    ))}
  </span>
);

const ModeControl = ({ modes, active, onSelect }) => (
  <div className="vast-tri-core__control">
    <svg viewBox="0 0 186 48" aria-hidden="true">
      <rect width="186" height="48" rx="24" fill="#000" />
      {MODE_DOT_PATHS.map((path, index) => <path key={index} d={path} fill="#fff" opacity={index <= active ? 1 : 0.18} />)}
    </svg>
    <div className="vast-tri-core__control-buttons" role="group" aria-label="Power mode">
      {modes.map((mode, index) => (
        <button type="button" key={mode.key} aria-label={mode.caption} aria-pressed={active === index} onClick={() => onSelect(index)} />
      ))}
    </div>
  </div>
);

export const VastTriCoreExperience = ({ data = {} }) => {
  const rootRef = useRef(null);
  const navigateRef = useRef(null);
  const [activeMood, setActiveMood] = useState(0);
  const {
    assetBase = PRIX_CDN,
    techEyebrow = 'Tri-core Mesh Technology',
    techTitle = 'One Pod, Three Experiences\nFor All MTL Vapers',
    moodEyebrow = 'Tri-core Mesh Technology',
    moodTitle = 'One Click To Switch\nYour Mood',
    desktopScrollDistance = 4800,
    mobileTechScrollDistance = 2000,
    mobileMoodScrollDistance = 2400,
    scrub = 0.65,
    pinOffset = 0,
    techEyebrowImage,
    moodEyebrowImage,
  } = data;

  const modes = useMemo(() => DEFAULT_MODES.map((defaults, index) => {
    const mode = { ...defaults, ...(data.modes?.[index] || {}) };
    return {
      ...mode,
      coilImage: mode.coilImage || asset(assetBase, mode.coilFile),
      productImage: mode.productImage || asset(assetBase, mode.productFile),
      sceneImage: mode.sceneImage || asset(assetBase, mode.sceneFile),
    };
  }), [assetBase, data.modes]);

  useIsomorphicLayoutEffect(() => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return undefined;
    const root = rootRef.current;
    if (!root) return undefined;
    let disposed = false;
    let media;
    let refreshFrame;

    const refresh = () => {
      if (disposed) return;
      cancelAnimationFrame(refreshFrame);
      refreshFrame = requestAnimationFrame(() => { if (!disposed) ScrollTrigger.refresh(); });
    };

    try {
      gsap.registerPlugin(ScrollTrigger);
      media = gsap.matchMedia();
      media.add({ desktop: '(min-width: 1024px)', mobile: '(max-width: 1023px)', reduced: '(prefers-reduced-motion: reduce)' }, (context) => {
        const { mobile, reduced } = context.conditions;
        const pin = root.querySelector('.vast-tri-core__pin');
        const overview = root.querySelector('.vast-tri-core__overview');
        const mood = root.querySelector('.vast-tri-core__mood');
        const techStage = root.querySelector('.vast-tri-core__tech-stage');
        const techModes = Array.from(root.querySelectorAll('.vast-tri-core__tech-mode'));
        const scenes = Array.from(root.querySelectorAll('.vast-tri-core__mood-scene'));
        const captions = Array.from(root.querySelectorAll('.vast-tri-core__mode-caption'));
        const offset = Math.max(0, Number(pinOffset) || 0);
        const follow = Math.max(0, Number(scrub) || 0);
        let lastMood = -1;

        const publishMood = (index) => {
          if (index === lastMood) return;
          lastMood = index;
          setActiveMood(index);
          root.dataset.mood = modes[index].key;
          scenes.forEach((scene, i) => scene.setAttribute('aria-hidden', String(i !== index)));
          captions.forEach((caption, i) => caption.setAttribute('aria-hidden', String(i !== index)));
        };
        publishMood(0);
        techModes.forEach((mode) => mode.removeAttribute('aria-hidden'));

        if (reduced) {
          // 系统减少动态效果时静态显示；指示灯仍可直接切换场景。
          navigateRef.current = (index) => {
            gsap.set(scenes, { autoAlpha: (i) => i === index ? 1 : 0 });
            gsap.set(captions, { autoAlpha: (i) => i === index ? 1 : 0 });
            publishMood(index);
          };
          return () => { navigateRef.current = null; };
        }

        gsap.set(scenes, { autoAlpha: (index) => index === 0 ? 1 : 0 });
        gsap.set(captions, { autoAlpha: (index) => index === 0 ? 1 : 0 });

        // 灰色页只有一份标题。以下时间线仅处理标题下面的图片与模式说明。
        const buildMoodSequence = (timeline, startAt, onSequenceUpdate) => {
          const boundaries = [];
          const landings = [startAt + 0.3];
          let time = startAt;
          for (let index = 1; index < 3; index += 1) {
            time += 1;
            const switchAt = time + 0.3;
            boundaries.push(switchAt);
            // timeline.to(scenes[index], { autoAlpha: 1, duration: 0.6, ease: 'power1.inOut' }, time);
            // timeline.to(captions[index - 1], { autoAlpha: 0, duration: 0.2 }, time);
            // timeline.to(captions[index], { autoAlpha: 1, duration: 0.25 }, time + 0.3);
            timeline.set([scenes[index - 1], captions[index - 1]], { autoAlpha: 0 }, switchAt);
            timeline.set([scenes[index], captions[index]], { autoAlpha: 1 }, switchAt);


            time += 0.6;
            landings.push(time + 0.3);
          }
          timeline.to({}, { duration: 1 }, time);
          timeline.eventCallback('onUpdate', () => {
            const current = timeline.time();
            onSequenceUpdate?.(current);
            publishMood(current >= boundaries[1] ? 2 : current >= boundaries[0] ? 1 : 0);
          });
          navigateRef.current = (index) => {
            const trigger = timeline.scrollTrigger;
            const progress = landings[index] / timeline.duration();
            window.scrollTo({ top: trigger.start + (trigger.end - trigger.start) * progress, behavior: 'smooth' });
          };
        };

        if (!mobile) {
          gsap.set(overview, { autoAlpha: 1 });
          gsap.set(mood, { autoAlpha: 0 });
          const techHeading = Array.from(overview.querySelectorAll('.vast-tri-core__eyebrow, .vast-tri-core__tech-title'));
          const moodHeading = Array.from(mood.querySelectorAll('.vast-tri-core__eyebrow, .vast-tri-core__mood-title'));

          const overviewEntrance = gsap.timeline({
            scrollTrigger: {
              trigger: root,
              start: 'top 75%',
              toggleActions: 'play none none none',
              once: true,
            },
          });
          overviewEntrance.fromTo(techHeading,
            { y: 32, autoAlpha: 0 },
            { y: 0, autoAlpha: 1, duration: 0.7, stagger: 0.12, ease: 'power3.out' }, 0);
          // gsap.fromTo(
          //   techModes,
          //   { x: 100, autoAlpha: 0 },
          //   {
          //     x: 0,
          //     autoAlpha: 1,
          //     duration: 0.85,
          //     stagger: 0.18,
          //     ease: 'power3.out',
          //     scrollTrigger: {
          //       trigger: techStage,
          //       start: 'top 70%',
          //       toggleActions: 'play none none none',
          //       once: true,
          //     },
          //   },
          // );
          // 外层不再整体移动，分别控制组内元素。
          gsap.set(techModes, { x: 0, autoAlpha: 1 });

          const cardsEntrance = gsap.timeline({
            scrollTrigger: {
              trigger: techStage,
              start: 'top 70%',
              toggleActions: 'play none none none',
              once: true,
            },
          });

          techModes.forEach((mode, index) => {
            const ruler = mode.querySelector('.vast-tri-core__ruler');
            const copy = mode.querySelector('.vast-tri-core__coil-copy');
            const image = mode.querySelector('.vast-tri-core__coil-image');

            // 每组间隔 1.65 秒。
            const start = index * 0.5;

            // 先出现 0.8Ω / 0.6Ω / 0.4Ω 和标尺，移动距离短。
            cardsEntrance.fromTo(
              ruler,
              { x: 40, autoAlpha: 0 },
              {
                x: 0,
                autoAlpha: 1,
                duration: 0.7,
                ease: 'power2.out',
              },
              start,
            );

            // 再出现指示灯、模式名称和说明，移动距离稍长。
            cardsEntrance.fromTo(
              copy,
              { x: 80, autoAlpha: 0 },
              {
                x: 0,
                autoAlpha: 1,
                duration: 0.85,
                ease: 'power2.out',
              },
              start + 0.3,
            );

            // 最后出现线圈图片，移动距离最长。
            cardsEntrance.fromTo(
              image,
              { x: 140, autoAlpha: 0 },
              {
                x: 0,
                autoAlpha: 1,
                duration: 1,
                ease: 'power2.out',
              },
              start + 0.65,
            );
          });
          const moodEntrance = gsap.timeline({ paused: true });
          moodEntrance.fromTo(moodHeading,
            { y: 32, autoAlpha: 0 },
            { y: 0, autoAlpha: 1, duration: 0.7, stagger: 0.12, ease: 'power3.out' }, 0);
          let moodEntered = false;

          const timeline = gsap.timeline({
            scrollTrigger: {
              trigger: root,
              start: () => `top top+=52`,
              end: () => `+=${distance(desktopScrollDistance, 4800)}`,
              pin,
              pinSpacing: true,
              scrub: follow,
              anticipatePin: 1,
              invalidateOnRefresh: true,
            },
          });
          timeline.to({}, { duration: 0.7 }, 0);
          timeline.to(overview, { autoAlpha: 0, duration: 0.6, ease: 'power1.inOut' }, 0.7);
          timeline.to(mood, { autoAlpha: 1, duration: 0.6, ease: 'power1.inOut' }, 0.7);
          buildMoodSequence(timeline, 1.3, (time) => {
            // 灰色页随主时间线淡入时，独立触发标题动画，只播放一次。
            if (time >= 0.7 && !moodEntered) {
              moodEntered = true;
              moodEntrance.play(0);
            }
          });
        } else {
          gsap.set(techModes, { autoAlpha: 1 });
          gsap.set(techStage, { x: 0 });
          const techPosition = (index) => -(techModes[index].offsetLeft - techModes[0].offsetLeft);

          // 原来的通用 to-top 移到本组件处理，避免与 PC 入场动画重复控制。
          [overview, mood].forEach((section) => {
            const heading = section.querySelector('header');
            gsap.fromTo(heading, { y: 28, autoAlpha: 0 }, {
              y: 0, autoAlpha: 1, duration: 0.7, ease: 'power3.out',
              scrollTrigger: { trigger: section, start: 'top 85%', once: true, toggleActions: 'play none none none' },
            });
          });

          const boundaries = [1.1, 2.7];
          let lastTech = -1;

          const techTimeline = gsap.timeline({
            scrollTrigger: {
              trigger: overview,
              start: () => 'top top+=44',
              end: () => `+=${distance(mobileTechScrollDistance, 2000)}`,
              pin: true,
              pinSpacing: true,
              scrub: follow,
              anticipatePin: 1,
              invalidateOnRefresh: true,
            },
          });

          techModes.forEach((mode, index) => {
            mode.setAttribute('aria-hidden', String(index !== 0));
          });

          techTimeline.to({}, { duration: 0.8 }, 0);

          techTimeline.fromTo(
            techStage,
            { x: 0 },
            {
              x: () => techPosition(1),
              duration: 0.6,
              ease: 'none',
              immediateRender: false,
            },
            0.8,
          );

          techTimeline.fromTo(
            techStage,
            { x: () => techPosition(1) },
            {
              x: () => techPosition(2),
              duration: 0.6,
              ease: 'none',
              immediateRender: false,
            },
            2.4,
          );

          techTimeline.to({}, { duration: 1 }, 3);
          const syncTechMode = () => {
            const time = techTimeline.time();
            const index = time >= boundaries[1] ? 2 : time >= boundaries[0] ? 1 : 0;
            if (index !== lastTech) {
              lastTech = index;
              root.dataset.techMode = modes[index].key;
              techModes.forEach((mode, i) => mode.setAttribute('aria-hidden', String(i !== index)));
            }
          };
          techTimeline.eventCallback('onUpdate', syncTechMode);
          syncTechMode();

          const moodTimeline = gsap.timeline({
            scrollTrigger: {
              trigger: mood,
              start: () => `top top+=44`,
              end: () => `+=${distance(mobileMoodScrollDistance, 2400)}`,
              pin: true,
              pinSpacing: true,
              scrub: follow,
              anticipatePin: 1,
              invalidateOnRefresh: true,
            },
          });
          buildMoodSequence(moodTimeline, 0);
        }
        return () => { navigateRef.current = null; };
      }, root);

      root.addEventListener('load', refresh, true);
      if (document.fonts?.ready) document.fonts.ready.then(refresh);
      refresh();
    } catch (error) {
      if (media) media.revert();
      root.classList.add('is-static');
      console.error('[VastTriCoreExperience] Animation initialization failed:', error);
    }

    return () => {
      disposed = true;
      cancelAnimationFrame(refreshFrame);
      root.removeEventListener('load', refresh, true);
      if (media) media.revert();
      navigateRef.current = null;
      root.classList.remove('is-static');
      root.removeAttribute('data-mood');
      root.removeAttribute('data-tech-mode');
    };
  }, [modes, desktopScrollDistance, mobileTechScrollDistance, mobileMoodScrollDistance, scrub, pinOffset]);

  return (
    <div className="vast-tri-core" ref={rootRef}>
      <div className="vast-tri-core__pin">
        <section className="vast-tri-core__overview" aria-label="Tri-core mesh technology">
          <header className="vast-tri-core__tech-header">
            <div className="vast-tri-core__eyebrow">
              <img src={techEyebrowImage} alt={techEyebrow} width="178" height="70" />
            </div>
            <h2 className="vast-tri-core__tech-title">{splitLines(techTitle)}</h2>
          </header>
          <div className="vast-tri-core__tech-stage">
            {modes.map((mode, index) => (
              <article className={`vast-tri-core__tech-mode vast-tri-core__tech-mode--${index + 1}`} key={mode.key}>
                <div className="vast-tri-core__ruler">
                  <div className="vast-tri-core__ruler-top"><strong>{mode.resistance}</strong><span aria-hidden="true" /></div>
                  <p>{mode.material || '\u00a0'}</p>
                </div>
                <div className="vast-tri-core__coil-area">
                  <Picture className="vast-tri-core__coil-image" image={mode.coilImage} mobileImage={mode.mobileCoilImage} alt={`${mode.name} mesh heating wire`} />
                  <div className="vast-tri-core__coil-copy">
                    <CoilLights count={index + 1} />
                    <h3>{mode.name}</h3>
                    <p>{splitLines(mode.description)}</p>
                  </div>
                </div>
              </article>
            ))}
          </div>
        </section>

        <section className="vast-tri-core__mood" aria-label="One click to switch your mood">
          <header className="vast-tri-core__mood-header">
            <div className="vast-tri-core__eyebrow">
              <img src={moodEyebrowImage} alt={moodEyebrow} width="178" height="70" />
            </div>
            <h2 className="vast-tri-core__mood-title">{splitLines(moodTitle)}</h2>
          </header>
          <div className="vast-tri-core__showcase to-top">
            {modes.map((mode, index) => (
              <div className={`vast-tri-core__mood-scene vast-tri-core__mood-scene--${index + 1}`} key={mode.key} aria-hidden={index !== 0}>
                <Picture className="vast-tri-core__scene-photo" image={mode.sceneImage} mobileImage={mode.mobileSceneImage} alt={mode.sceneAlt || mode.caption} style={{ '--scene-position': mode.position }} />
                <Picture className="vast-tri-core__product-image" image={mode.productImage} mobileImage={mode.mobileProductImage} alt={`${mode.name} device indicator`} />
              </div>
            ))}
          </div>
          <ModeControl modes={modes} active={activeMood} onSelect={(index) => navigateRef.current?.(index)} />
          <div className="vast-tri-core__mode-captions" aria-live="polite" aria-atomic="true">
            {modes.map((mode, index) => <p className={`vast-tri-core__mode-caption vast-tri-core__mode-caption--${index + 1}`} key={mode.key} aria-hidden={index !== activeMood}>{mode.caption}</p>)}
          </div>
        </section>
      </div>
    </div>
  );
};

export default VastTriCoreExperience;
